// Report every component that is not OK or deliberately DISABLED.
// 'DEGRADED' matters: it is how the gateway says it fell back to the lexical
// embedder or the database vector store, which is easy to run for months
// without noticing.
const h = $input.first().json;
const problems = (h.components || []).filter(c => !['OK', 'DISABLED'].includes(c.status));
return [{ json: {
  overall: h.status,
  problems,
  needs_attention: problems.length > 0 || h.status !== 'ok'
} }];
